#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int v; struct Node *l, *r; } Node;
static Node *mk(int v) { Node *n = malloc(sizeof(Node)); n->v = v; n->l = n->r = NULL; return n; }

/* 返回子树高度；发现不平衡返回 -1（哨兵短路）。
   返回值同时携带「高度」与「是否平衡」两种信息 —— 树形 DP 通用技巧。 */
static int check(Node *n) {
    if (!n) return 0;
    int lh = check(n->l);
    if (lh == -1) return -1;
    int rh = check(n->r);
    if (rh == -1) return -1;
    int d = lh - rh;
    if (d > 1 || d < -1) return -1;
    return 1 + (lh > rh ? lh : rh);
}

int main(void) {
    /* 平衡树 */
    Node *a = mk(1), *b = mk(2), *c = mk(3), *d = mk(4), *e = mk(5);
    a->l = b; a->r = c; b->l = d; b->r = e;
    printf("树 1 是否平衡: %s\n", check(a) != -1 ? "是" : "否");

    /* 左斜链（高度差 3） */
    Node *x = mk(1), *y = mk(2), *z = mk(3), *w = mk(4);
    x->l = y; y->l = z; z->l = w;
    printf("树 2 是否平衡: %s\n", check(x) != -1 ? "是" : "否");
    return 0;
}
